                           and all(isinstance(r, str) for r in v),
    }
    for field, ok in checks.items():
        if field not in payload:
            errors.append(f"missing: {field}")
        elif not ok(payload[field]):
            errors.append(f"invalid: {field}")
    return sorted(errors)
```

O(n). The `bool` check is the trap: `isinstance(True, int)` is True in Python, so `id: true` would slip through. In a real suite you'd express these rules with jsonschema or a pydantic model, but interviewers ask for the manual version to see whether you think about missing vs invalid and type edge cases.

