from dataclasses import dataclass

@dataclass
class TestResult:
    name: str
    status: str
    duration: float = 0.0

    @property
    def passed(self):
        return self.status == "passed"

def fastest_passed(results):
    passing = [r for r in results if r.passed]
    return min(passing, key=lambda r: r.duration).name if passing else None

